    public static void testQuarterTurnsAreClockwiseAndFourMakeNone() {
        // A 3x2 picture, left to right and top to bottom 1..6; one clockwise turn makes a 2x3 picture whose rows are
        // [4 1], [5 2], [6 3].
        emon.Port.Bitmap s = emon.Port.bitmapNew(3, 2, 1);
        emon.Port.Bitmap q = emon.Port.bitmapNew(2, 3, 1);
        emon.Port.Bitmap h = emon.Port.bitmapNew(3, 2, 1);
        emon.Port.Bitmap w = emon.Port.bitmapNew(2, 3, 1);
        emon.Port.Bitmap z = emon.Port.bitmapNew(3, 2, 1);
        emon.Port.bitmapSetU8(s, 0, 0, 0, 1);
        emon.Port.bitmapSetU8(s, 1, 0, 0, 2);
        emon.Port.bitmapSetU8(s, 2, 0, 0, 3);
        emon.Port.bitmapSetU8(s, 0, 1, 0, 4);
        emon.Port.bitmapSetU8(s, 1, 1, 0, 5);
        emon.Port.bitmapSetU8(s, 2, 1, 0, 6);
        emon.Port.bitmapQuarterInto(s, q, 1);
        emon.Testport.assertEq(emon.Port.bitmapU8(q, 0, 0, 0), 4, "row 0, col 0");
        emon.Testport.assertEq(emon.Port.bitmapU8(q, 1, 0, 0), 1, "row 0, col 1");
        emon.Testport.assertEq(emon.Port.bitmapU8(q, 0, 1, 0), 5, "row 1, col 0");
        emon.Testport.assertEq(emon.Port.bitmapU8(q, 1, 1, 0), 2, "row 1, col 1");
        emon.Testport.assertEq(emon.Port.bitmapU8(q, 0, 2, 0), 6, "row 2, col 0");
        emon.Testport.assertEq(emon.Port.bitmapU8(q, 1, 2, 0), 3, "row 2, col 1");
        emon.Port.bitmapQuarterInto(s, h, 2);
        emon.Testport.assertEq(emon.Port.bitmapU8(h, 0, 0, 0), 6, "two turns: the last pixel comes first");
        emon.Testport.assertEq(emon.Port.bitmapU8(h, 2, 1, 0), 1, "and the first comes last");
        emon.Port.bitmapQuarterInto(s, w, 3);
        emon.Testport.assertEq(emon.Port.bitmapU8(w, 0, 0, 0), 3, "three turns: row 0, col 0 is the old top right");
        emon.Testport.assertEq(emon.Port.bitmapU8(w, 1, 2, 0), 4, "and the old bottom left is at the far corner");
        emon.Port.bitmapQuarterInto(s, q, 1);
        emon.Port.bitmapQuarterInto(q, z, 1);
        emon.Port.bitmapQuarterInto(z, q, 1);
        emon.Port.bitmapQuarterInto(q, h, 1);
        emon.Testport.assertEq(ntSame(s, h), 1, "four single turns are the identity");
    }
