    public static int ntSauvCase(emon.Port.Bitmap g, emon.Port.Cells sq) {
        // 1 when the banded form (r = 15, k = 87) equals the whole-page ras-sauvola, mask and ink count.
        emon.Port.Bitmap a = emon.Port.bitmapNew(emon.Port.bitmapW(g), emon.Port.bitmapH(g), 1);
        emon.Port.Bitmap b = emon.Port.bitmapNew(emon.Port.bitmapW(g), emon.Port.bitmapH(g), 1);
        emon.Port.Cells isum = emon.Port.newCells();
        emon.Port.Cells isq = emon.Port.newCells();
        emon.Port.Cells sv = emon.Port.newCells();
        int n1 = rasSauvolaWhole(g, isum, isq, sq, a);
        int n2 = Norm.nmSauvola(g, b, 15, 87, sv);
        if (n1 != n2) {
            return 0;
        }
        return ntSame(a, b);
    }
