    public static void testReskewRebuildsAViewsTransformInPlace() {
        emon.Port.Cells views = emon.Port.newCells();
        emon.Port.Cells ref = emon.Port.newCells();
        Evidence.vwNew(views, 3, Evidence.vkDecode(), 7, -1, 200, 100, 20000, 0, -1, 1, 0, 500, 600, 0);
        Evidence.vwNew(views, 3, Evidence.vkGray(), -1, 0, 200, 100, 20000, 0, -1, 1, 0, 500, 600, 0);
        Evidence.vwNew(ref, 3, Evidence.vkDecode(), 7, -1, 200, 100, 20000, 0, -1, 1, 150, 500, 600, 0);
        emon.Testport.assertEq(Norm.nmReskew(views, 0, 150), 0, "reskew");
        emon.Testport.assertEq(Evidence.vwCount(views), 2, "no row left behind");
        emon.Testport.assertEq(Evidence.vwGet(views, 0, Evidence.vwfDeskew()), 150, "the angle");
        emon.Testport.assertEq(Evidence.vwGet(views, 0, Evidence.vwfA()), Evidence.vwGet(ref, 0, Evidence.vwfA()), "a");
        emon.Testport.assertEq(Evidence.vwGet(views, 0, Evidence.vwfB()), Evidence.vwGet(ref, 0, Evidence.vwfB()), "b");
        emon.Testport.assertEq(Evidence.vwGet(views, 0, Evidence.vwfC()), Evidence.vwGet(ref, 0, Evidence.vwfC()), "c");
        emon.Testport.assertEq(Evidence.vwGet(views, 0, Evidence.vwfD()), Evidence.vwGet(ref, 0, Evidence.vwfD()), "d");
        emon.Testport.assertEq(Evidence.vwGet(views, 0, Evidence.vwfE()), Evidence.vwGet(ref, 0, Evidence.vwfE()), "e");
        emon.Testport.assertEq(Evidence.vwGet(views, 0, Evidence.vwfF()), Evidence.vwGet(ref, 0, Evidence.vwfF()), "f");
        emon.Testport.assertEq(Evidence.vwGet(views, 1, Evidence.vwfDeskew()), 0, "the neighbouring row is untouched");
    }
    public static void testNmViewMakesTheDerivedViewsTheInkRowsAndTheMasks() {
        emon.Port.Bitmap src = emon.Port.bitmapNew(100, 80, 3);
        emon.Port.Bitmap gray = emon.Port.bitmapNew(100, 80, 1);
        emon.Port.Bitmap bin = emon.Port.bitmapNew(100, 80, 1);
        emon.Port.Bitmap ref = emon.Port.bitmapNew(100, 80, 1);
        emon.Port.Bitmap m = emon.Port.bitmapNew(100, 80, 1);
        emon.Port.Cells views = emon.Port.newCells();
        emon.Port.Cells inks = emon.Port.newCells();
        emon.Port.Cells ws = emon.Port.newCells();
        emon.Port.Cells sv = emon.Port.newCells();
        emon.Port.Cells aux = emon.Port.newCells();
        ntPage3(src);
        Evidence.vwNew(views, 5, Evidence.vkRender(), 2, -1, 100, 80, 15000, 0, -1, 0, 0, 0, 0, 0);
        emon.Testport.assertEq(Norm.nmView(views, inks, 5, 0, src, gray, bin, ws, sv, aux), 3, "three ink layers");
        Norm.nmRefGray(src, ref);
        emon.Testport.assertEq(ntSame(gray, ref), 1, "the gray view is the bulk form's");
        emon.Testport.assertEq(Evidence.vwCount(views), 6, "the render, gray, binary and three masks");
        emon.Testport.assertEq(Norm.nmGrayView(ws), 1, "the gray view's row");
        emon.Testport.assertEq(Norm.nmBinaryView(ws), 2, "the binary view's row");
        emon.Testport.assertEq(Evidence.vwGet(views, 1, Evidence.vwfKind()), Evidence.vkGray(), "its kind");
        emon.Testport.assertEq(Evidence.vwGet(views, 2, Evidence.vwfKind()), Evidence.vkBinary(), "binary");
        emon.Testport.assertEq(Evidence.vwGet(views, 1, Evidence.vwfParent()), 0, "parented on the render");
        emon.Testport.assertEq(Evidence.ikCount(inks), 3, "three inks rows");
        emon.Testport.assertEq(Evidence.ikGet(inks, 1, Evidence.ikfRole()), Evidence.irBody(), "the second is the body");
        emon.Testport.assertEq(Evidence.ikGet(inks, 1, Evidence.ikfMask()), 4, "and its mask view is row 4");
        emon.Testport.assertEq(Evidence.vwGet(views, 4, Evidence.vwfKind()), Evidence.vkInkMask(), "of kind ink-mask");
        Norm.nmMaskInto(src, ws, 2, m);
        emon.Testport.assertEq(ntCount(m), 620, "the body mask the caller makes for it");
        emon.Testport.assertEq(Evidence.vwGet(views, 0, Evidence.vwfDeskew()), 0, "a render is not deskewed");
        Norm.nmSauvola(gray, ref, 8, 87, sv);
        emon.Testport.assertEq(ntSame(bin, ref), 1, "the binary view is Sauvola at r = 8 for 150 dpi");
    }
    public static void testNmViewOfABilevelSourceSkipsSauvola() {
        emon.Port.Bitmap src = emon.Port.bitmapNew(40, 20, 1);
        emon.Port.Bitmap gray = emon.Port.bitmapNew(40, 20, 1);
        emon.Port.Bitmap bin = emon.Port.bitmapNew(40, 20, 1);
        emon.Port.Cells views = emon.Port.newCells();
        emon.Port.Cells inks = emon.Port.newCells();
        emon.Port.Cells ws = emon.Port.newCells();
        emon.Port.Cells sv = emon.Port.newCells();
        emon.Port.Cells aux = emon.Port.newCells();
        ntRect(src, 0, 0, 40, 20, 255, 0, 0);
        ntRect(src, 5, 5, 15, 15, 0, 0, 0);
        Evidence.vwNew(views, 0, Evidence.vkRender(), -1, -1, 40, 20, 15000, 0, -1, 0, 0, 0, 0, 1);
        Norm.nmView(views, inks, 0, 0, src, gray, bin, ws, sv, aux);
        emon.Testport.assertEq(ntCount(bin), 100, "the black block, in full: a threshold, not a local one");
        emon.Testport.assertEq(emon.Port.cellsLen(sv), 0, "and Sauvola's scratch was never needed");
    }
    public static void testNmViewMeasuresTheSkewOfADecodeAndWritesItEverywhere() {
        emon.Port.Bitmap src = emon.Port.bitmapNew(1000, 700, 3);
        emon.Port.Bitmap gray = emon.Port.bitmapNew(1000, 700, 1);
        emon.Port.Bitmap bin = emon.Port.bitmapNew(1000, 700, 1);
        emon.Port.Cells views = emon.Port.newCells();
        emon.Port.Cells inks = emon.Port.newCells();
        emon.Port.Cells ws = emon.Port.newCells();
        emon.Port.Cells sv = emon.Port.newCells();
        emon.Port.Cells aux = emon.Port.newCells();
        ntRect(src, 0, 0, 1000, 700, 255, 255, 255);
        ntTextLines(src, 150, 0);
        Evidence.vwNew(views, 0, Evidence.vkDecode(), -1, -1, 1000, 700, 15000, 0, -1, 0, 0, 0, 0, 0);
        emon.Testport.assertEq(Norm.nmView(views, inks, 0, 0, src, gray, bin, ws, sv, aux), 1, "one ink layer");
        emon.Testport.assertEq(ntNear(Evidence.vwGet(views, 0, Evidence.vwfDeskew()), 150, 15), 1, "the decode view carries the skew");
        emon.Testport.assertEq(Evidence.vwGet(views, 1, Evidence.vwfDeskew()), Evidence.vwGet(views, 0, Evidence.vwfDeskew()), "so does the gray view");
        emon.Testport.assertEq(Evidence.vwGet(views, 2, Evidence.vwfDeskew()), Evidence.vwGet(views, 0, Evidence.vwfDeskew()), "and the binary");
        emon.Testport.assertEq(Evidence.vwGet(views, 3, Evidence.vwfDeskew()), Evidence.vwGet(views, 0, Evidence.vwfDeskew()), "and the mask");
    }
    public static void testARunLongerThanTheCapIsNotASkewPoint() {
        emon.Port.Bitmap b = emon.Port.bitmapNew(200, 10, 1);
        emon.Port.Cells pts = emon.Port.newCells();
        ntRect(b, 10, 3, 20, 4, 255, 0, 0);
        ntRect(b, 40, 3, 190, 4, 255, 0, 0);
        emon.Testport.assertEq(Norm.nmSkewPointsCap(b, pts, 1, 100, 50), 1, "a rule 150 px long is not a text cluster at a cap of 50: its midpoint stands for none of its pixels");
        emon.Testport.assertEq(emon.Port.cellsAt(pts, 2), 10, "the short run is the point");
        emon.Testport.assertEq(Norm.nmSkewPointsCap(b, pts, 1, 100, 150), 2, "at a cap of 150 both are");
        emon.Testport.assertEq(Norm.nmSkewPoints(b, pts, 1, 100), 2, "and `nm-skew-points` has no cap");
    }
    public static void testAPageOfARuledTableAndNoTextIsNotSkewed() {
        emon.Port.Bitmap b = emon.Port.bitmapNew(1000, 700, 1);
        emon.Port.Cells pts = emon.Port.newCells();
        emon.Port.Cells prof = emon.Port.newCells();
        int k = 0;
        // a 500 x 300 table, 3 px rules: seven rows of lines, five columns; nothing else on the page
        while (k < 8) {
            ntRect(b, 250, 200 + (k * 43), 750, (200 + (k * 43)) + 3, 255, 0, 0);
            k += 1;
        }
        k = 0;
        while (k < 6) {
            ntRect(b, 250 + (k * 99), 200, (250 + (k * 99)) + 3, 503, 255, 0, 0);
            k += 1;
        }
        emon.Testport.assertEq(Norm.nmDeskew(b, pts, prof), 0, "rules are not lines of text: a table alone has no skew to find");
    }
